private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null || node.left == null) {
        return node;
    }
    TreeNode<T> left = node.left;
    // detach left's right subtree and attach to node
    node.left = left.right;
    if (left.right != null) {
        left.right.parent = node;
    }
    // rewire parent links
    left.parent = node.parent;
    if (node.parent == null) {
        // node was root; left becomes new root (parent set to null)
        left.parent = null;
    } else if (node == node.parent.right) {
        node.parent.right = left;
    } else {
        node.parent.left = left;
    }
    // finish rotation
    left.right = node;
    node.parent = left;
    return left;
}

