    // Acquire locks on both lists to ensure atomicity of the move operation
    synchronized (this) {
        synchronized (list) {
            // Start from the head of the source list
            ListNode<E> current = list.getFirstNode();
            while (current != null) {
                // Save reference to the next node before we modify the current one
                ListNode<E> next = current.getNext();
                // Remove the node from the source list
                list.removeListNode(current);
                // Add the node to this list
                this.addListNode(current);
                // Move to the next node in the source list
                current = next;
            }
        }
    }
}

