    if (path == null || path.isEmpty()) {
        return segments;
    }
    // Remove leading '/' for absolute paths
    if (path.startsWith("/")) {
        path = path.substring(1);
    }
    String[] parts = path.split("/");
    for (String part : parts) {
        if (part.isEmpty()) {
            continue;
        }
        String decoded = part;
        if (decode) {
            try {
                decoded = URLDecoder.decode(part, StandardCharsets.UTF_8.name());
            } catch (UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as unchecked
                throw new RuntimeException(e);
            }
        }
        segments.add(new PathSegmentImpl(part, decoded));
    }
    return segments;
}

