        return null;
    }
    if (charsToDelete == null || charsToDelete.isEmpty()) {
        return inString;
    }
    // Use a boolean array for quick lookup of characters to delete
    boolean[] deleteMap = new boolean[Character.MAX_VALUE + 1];
    for (int i = 0; i < charsToDelete.length(); i++) {
        deleteMap[charsToDelete.charAt(i)] = true;
    }
    StringBuilder sb = new StringBuilder(inString.length());
    for (int i = 0; i < inString.length(); i++) {
        char c = inString.charAt(i);
        if (!deleteMap[c]) {
            sb.append(c);
        }
    }
    return sb.toString();
}

