public static String applyRelativePath(String path, String relativePath) {
    if (path == null) {
        throw new IllegalArgumentException("path cannot be null");
    }
    if (relativePath == null) {
        return path;
    }
    try {
        boolean leadingSlash = path.startsWith("/");
        java.util.Deque<String> stack = new java.util.ArrayDeque<>();

        // Process base path
        for (String part : path.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(part);
            }
        }

        // Process relative path
        for (String part : relativePath.split("/")) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            }
            if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.removeLast();
                }
            } else {
                stack.addLast(part);
            }
        }

        StringBuilder result = new StringBuilder();
        if (leadingSlash) {
            result.append("/");
        }
        java.util.Iterator<String> it = stack.iterator();
        while (it.hasNext()) {
            result.append(it.next());
            if (it.hasNext()) {
                result.append("/");
            }
        }

        // If result is empty, return "." to represent current directory
        return result.length() == 0 ? "." : result.toString();
    } catch (Exception e) {
        throw new IllegalArgumentException("Failed to apply relative path", e);
    }
}

