protected int removeUnusedNodes(){
    int removedCount = 0;
    try {
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, drop the entire tree
        if (!root.isActive()) {
            root = null;
            return 1;
        }
        Deque<CategoryNode> stack = new ArrayDeque<>();
        stack.push(root);
        while (!stack.isEmpty()) {
            CategoryNode current = stack.pop();
            List<CategoryNode> children = current.getChildren();
            if (children != null) {
                Iterator<CategoryNode> it = children.iterator();
                while (it.hasNext()) {
                    CategoryNode child = it.next();
                    if (!child.isActive()) {
                        it.remove();
                        removedCount++;
                    } else {
                        stack.push(child);
                    }
                }
            }
        }
    } catch (Exception e) {
        if (LOG != null) {
            LOG.error("Error while removing unused nodes", e);
        }
    }
    return removedCount;
}

