protected List<TimeRange> buildTimeRanges(long start,long end){
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }
    if (start > end) {
        throw new IllegalArgumentException("start must be less than or equal to end");
    }
    List<TimeRange> ranges = new ArrayList<>();
    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        if (next <= current || next > end) { // handle overflow or overshoot
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

