public static LinkedBuffer writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    if (lb == null) {
        throw new IllegalArgumentException("LinkedBuffer cannot be null");
    }
    if (str == null) {
        return lb;
    }
    try {
        byte[] bytes = str.toString().getBytes(java.nio.charset.StandardCharsets.UTF_8);
        lb.write(bytes, 0, bytes.length);
    } catch (Exception e) {
        // Fallback to platform default encoding if UTF-8 fails
        try {
            byte[] bytes = str.toString().getBytes();
            lb.write(bytes, 0, bytes.length);
        } catch (Exception ex) {
            // ignore further failures
        }
    }
    return lb;
}

